insert into public.t3a_field_prohibited_item (dictionary_version, item_no, item, reason, use_instead)
select '1.3', t.ord::integer, t.j->>'item', t.j->>'reason', t.j->>'use_instead'
from jsonb_array_elements($dict$[{"item":"score, rating, rank, percentile, BARS label, behavioral_score, readiness_score, ordinal_anchor","reason":"Scoring is retired; nothing reintroduces scores, ratings or scales","use_instead":"Determinations, state_code and Recorded Conduct Entries"},{"item":"level_1 to level_4, observation_level, L1 to L4","reason":"Retired vocabulary","use_instead":"stage_code S1 to S4"},{"item":"tier, band, Silver, Gold, Platinum, match or matching value, BehaviourMatch","reason":"Tier logic and matching are retired","use_instead":"talentvisa_active (two states) and employer_visibility_state"},{"item":"skill_passport","reason":"Retired outright; historical rows read only","use_instead":"Behavioral Evidence Report"},{"item":"endorsement, endorse, recommend as a mentor action","reason":"Retired","use_instead":"Confirmation (S1) and progression_decision"},{"item":"escalate as a progression state","reason":"Progression has three states only","use_instead":"Incident and welfare routes"},{"item":"validation_status or any identifier containing validate","reason":"Forbidden identifier","use_instead":"None"},{"item":"fingerprint in any identifier","reason":"Retired term","use_instead":"Longitudinal Behavioral Pattern Methodology (dormant consumer)"},{"item":"dimensions_flagged, dimension_scores","reason":"Evaluative flags outside determinations","use_instead":"Determinations"},{"item":"ai_score_override, ai_assist_notes_accepted, ai_assist_notes_ignored, any AI suggestion to a mentor","reason":"No AI suggestion or auto selection exists","use_instead":"None"},{"item":"free text mentor conclusion, evidence_notes as free text, decision rationale as free text","reason":"Free text never reaches the record","use_instead":"Controlled codes"},{"item":"has_rehearsed or any rehearsal flag on the evidence side; any join key between rehearsal and evidence stores","reason":"Firewall","use_instead":"Aggregate telemetry sink only"},{"item":"accommodation reason, diagnosis or medical detail","reason":"Never stored","use_instead":"accommodation_class only"},{"item":"race, ethnicity, gender identity, sexual orientation, disability, religion, immigration status, date of birth in operational stores","reason":"Default exclusion list","use_instead":"Research socket only, separately approved"},{"item":"mood, personality, trait, character, potential or risk label","reason":"Proxy inference","use_instead":"None"},{"item":"predicted performance, retention, probation or success fields","reason":"No prediction","use_instead":"None"},{"item":"hire, reject, still employed, probation outcome, rehire intention, performance rating linked to a participant","reason":"Outcome claims prohibited","use_instead":"Unlinked hire_recorded_row and the disabled follow up socket"},{"item":"biometric fields (face, voice, keystroke, gaze)","reason":"Excluded","use_instead":"None"},{"item":"social media or public record scraping fields","reason":"Excluded","use_instead":"None"},{"item":"shortlist or exclusion flag; governance.tier_change; mentor.override_requested for a fourth attempt","reason":"Retired constructs","use_instead":"None"},{"item":"any shared table, template, name or data path between the Behavioral Evidence Report and an employer commissioned competence record","reason":"Separation test","use_instead":"Separate enterprise product, not in this platform build"},{"item":"any event, field or link between Civic Access Lab and this platform","reason":"Excluded","use_instead":"None"},{"item":"card numbers, bank account numbers, government identification numbers","reason":"Never stored","use_instead":"payment_provider_ref token"}]$dict$::jsonb) with ordinality as t(j, ord)
on conflict (dictionary_version, item_no) do nothing;

-- A load that did not land exactly as the dictionary states is refused.
do $$
declare n_fields integer; n_prohibited integer; n_active integer; n_socket integer; n_dormant integer;
begin
  select count(*) into n_fields from public.t3a_field_registry where dictionary_version = '1.3';
  select count(*) into n_prohibited from public.t3a_field_prohibited_item where dictionary_version = '1.3';
  select count(*) filter (where status = 'ACTIVE'), count(*) filter (where status = 'SOCKET'), count(*) filter (where status = 'DORMANT')
    into n_active, n_socket, n_dormant from public.t3a_field_registry where dictionary_version = '1.3';
  if n_fields <> 600 or n_prohibited <> 23 then
    raise exception 'T3A_REGISTRY_LOAD_MISMATCH: expected 600 fields and 23 prohibited items, found % and %', n_fields, n_prohibited;
  end if;
  raise notice 'field registry 1.3 loaded: % fields (% ACTIVE, % DORMANT, % SOCKET), % prohibited items', n_fields, n_active, n_dormant, n_socket, n_prohibited;
end $$;
